    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.26.0/ankra-cli-linux-arm64"
      sha256 "d004685df642b6be873ee7395521fddc04f49d7270df204430b3344bad4af58e"
    end
    on_intel do
